/bin/bash -lc "python3 - <<'PY'
from openai_client import OpenAIClient, extract_output_text

response = {
    'output': [
        {'type': 'message', 'content': [
            {'type': 'output_text', 'text': 'hello'},
            {'type': 'output_text', 'text': ' world'},
        ]}
    ]
}
assert extract_output_text(response) == 'hello world'
assert extract_output_text({'output_text': 'direct'}) == 'direct'
client = OpenAIClient(api_key='[REDACTED_SECRET]')
try:
    client.create_response('x', extra_body={'store': True})
except ValueError as exc:
    assert 'store' in str(exc)
else:
    raise AssertionError('reserved extra_body key accepted')
print('ok')
PY"

